package com.brooklyn.annoyancemute;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.lang.reflect.Type;
import java.nio.charset.StandardCharsets;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import javax.annotation.Nullable;
import lombok.extern.slf4j.Slf4j;

/**
 * Names of the sound effects (SoundEffectID) and the location based ambient sounds (AmbientSoundID), read from the json
 * files in the resources folder. Generated by scripts/update_sound_names.py. The files are read the first time they
 * are needed, and a file that is missing or broken just leaves that lookup empty.
 */
@Slf4j
public class SoundNames
{
	private static final String SOUND_NAMES_RESOURCE = "sound_names.json";
	private static final String AMBIENT_SOUND_NAMES_RESOURCE = "ambient_sound_names.json";
	private static final Type NAME_TO_ID = new TypeToken<Map<String, Integer>>()
	{
	}.getType();

	private final Gson gson;

	// name -> id
	private volatile Map<String, Integer> soundIds;
	// id -> name, when several names share an id the first one in the file is used
	private volatile Map<Integer, String> soundNames;
	private volatile Map<Integer, String> ambientSoundNames;

	public SoundNames(Gson gson)
	{
		this.gson = gson;
	}

	/**
	 * Turns one entry of a muted sounds config into a sound id. The entry is either the id itself or the name of a
	 * sound effect, in any case.
	 *
	 * @return the id, or null when the entry is neither a number nor a known name
	 */
	@Nullable
	public Integer resolveSoundId(@Nullable String entry)
	{
		if (entry == null)
		{
			return null;
		}

		String trimmed = entry.trim();
		if (trimmed.isEmpty())
		{
			return null;
		}

		try
		{
			return Integer.parseInt(trimmed);
		}
		catch (NumberFormatException e)
		{
			return getSoundIds().get(trimmed.toLowerCase());
		}
	}

	@Nullable
	public String getSoundName(int soundId)
	{
		return getSoundNamesById().get(soundId);
	}

	@Nullable
	public String getAmbientSoundName(int ambientSoundId)
	{
		Map<Integer, String> names = ambientSoundNames;
		if (names == null)
		{
			names = invert(load(AMBIENT_SOUND_NAMES_RESOURCE));
			ambientSoundNames = names;
		}
		return names.get(ambientSoundId);
	}

	private Map<String, Integer> getSoundIds()
	{
		Map<String, Integer> ids = soundIds;
		if (ids == null)
		{
			ids = load(SOUND_NAMES_RESOURCE);
			soundIds = ids;
		}
		return ids;
	}

	private Map<Integer, String> getSoundNamesById()
	{
		Map<Integer, String> names = soundNames;
		if (names == null)
		{
			names = invert(getSoundIds());
			soundNames = names;
		}
		return names;
	}

	private Map<String, Integer> load(String resource)
	{
		try (InputStream stream = SoundNames.class.getResourceAsStream(resource))
		{
			if (stream == null)
			{
				log.warn("Sound names file {} not found", resource);
				return Collections.emptyMap();
			}

			Map<String, Integer> names = gson.fromJson(new InputStreamReader(stream, StandardCharsets.UTF_8), NAME_TO_ID);
			return names == null ? Collections.emptyMap() : names;
		}
		catch (IOException | RuntimeException e)
		{
			log.warn("Could not read sound names file {}", resource, e);
			return Collections.emptyMap();
		}
	}

	private static Map<Integer, String> invert(Map<String, Integer> names)
	{
		Map<Integer, String> inverted = new HashMap<>(names.size() * 4 / 3 + 1);
		for (Map.Entry<String, Integer> entry : names.entrySet())
		{
			// null values can't be in a gson map of Integer unless the file has a literal null
			if (entry.getValue() != null)
			{
				inverted.putIfAbsent(entry.getValue(), entry.getKey());
			}
		}
		return inverted;
	}
}
